#!/bin/bash
sed -i 's|"github.com/davosjar/bunna/services/fincas/internal/application/usecases/rechazardiagnostico"|"github.com/davosjar/bunna/services/fincas/internal/application/usecases/rechazardiagnostico"\n\t"github.com/davosjar/bunna/services/fincas/internal/application/usecases/registrarinferencia"|' fincas/internal/presentation/facades/diagnostico_facade.go
sed -i 's|RechazarDiagnosticoUseCase interface {|RegistrarInferenciaUseCase interface {\n\t\tEjecutar(ctx context.Context, cmd registrarinferencia.Command) (*registrarinferencia.Salida, error)\n\t}\n\tRechazarDiagnosticoUseCase interface {|' fincas/internal/presentation/facades/diagnostico_facade.go
